      "path": "src/routekit/hub_depots.py",
      "content": "from typing import Iterable, List, Tuple
from collections import Counter

def hub_depots(edges: Iterable[Tuple[str, str, int]], top_n: int) -> List[Tuple[str, int]]:
    if top_n < 1:
        raise ValueError("top_n must be at least 1")

    degrees = Counter()
    all_depots = set()
    for u, v, w in edges:
        all_depots.add(u)
        all_depots.add(v)
        if u != v:
            degrees[u] += 1
            degrees[v] += 1

    ranked = sorted(((code, degrees[code]) for code in all_depots), key=lambda item: (-item[1], item[0]))

    if not ranked:
        return []
    if len(ranked) <= top_n:
        return ranked

    cutoff = ranked[top_n - 1][1]
    return [item for item in ranked if item[1] >= cutoff]"
    }
  }
}
